        def mmax(path):
            err = subprocess.run(['ffmpeg', '-hide_banner', '-nostats', '-i', str(path), '-af', 'ebur128=metadata=1,ametadata=print:key=lavfi.r128.M', '-f', 'null', '-'], capture_output=True, text=True).stderr
            return max((float(v) for v in re.findall('lavfi\\.r128\\.M=(-?[\\d.]+)', err) if float(v) > -100))
        m0 = mmax(p)
        o = Path(wd) / ('%s.wav' % k)
        g = target - m0
        for _ in range(3):
            ff('-i', p, '-af', 'volume=%.3fdB,alimiter=limit=%.4f:level=false' % (g, 10 ** (-1 / 20)), o)
            got[k] = mmax(o)
            if abs(got[k] - target) <= 0.3:
                break
            g += target - got[k]
        outs.append(o)
    raw_m = got
    return ([check("each SFX's max momentary loudness sits on its tier (±1 LU)", all((abs(got[k] - tiers[k]) <= 1.0 for k in tiers)), got, tiers), check('ceiling -1 dBFS', all((peak_db(load_any(o)[0]) <= -0.95 for o in outs)), [peak_db(load_any(o)[0]) for o in outs], '<= -1'), check('negative control: raw files share one level, not tiers', len({round(peak_db(load_any(Path(wd) / ('%s_raw.wav' % k))[0]), 1) for k in tiers}) == 1, sorted({round(peak_db(load_any(Path(wd) / ('%s_raw.wav' % k))[0]), 1) for k in tiers}), 'one level')], outs)

def card(task, wd):
    c1, o1 = _loud(wd, -14, -1, 11, name='web', post='alimiter=limit=0.89:level=false', tol=1.0)
    c2, o2 = _loud(wd, -18, -1.5, 11, name='bed', post='alimiter=limit=0.84:level=false')
    return (c1 + c2, o1 + o2)
